INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('99f78755-9511-5ac5-9f4e-57e1493de5b1','TEXT','A Lantern for the Jetty','Sienna liked helping at the sea fog, especially when there was a small job that nobody had planned. One Thursday, Sienna noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
