INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('089ab09c-5d42-52a4-86dd-271ee663811c','TEXT','The Rainwater Notebook','Ruby liked helping at the school courtyard, especially when there was a small job that nobody had planned. One Tuesday, Ruby noticed the rain gauge was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2bbe6b8d-bd6c-535f-9376-daa792771c86','TEXT','The Paper Kite Map — A Different Day','Luca liked helping at the open oval, especially when there was a small job that nobody had planned. One Tuesday, Luca noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
