INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0f193411-0a5a-5c57-ab3d-3ce1be584ea6','TEXT','The Paper Kite Map','Luca liked helping at the open oval, especially when there was a small job that nobody had planned. One Friday, Luca noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('252f1431-9fd3-5816-b64c-3d8f315d78e4','TEXT','The Night Garden List — A Different Day','Zoe liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Saturday, Zoe noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
