INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b9c56854-c06b-529f-9c27-2df17cc29169','TEXT','The Bicycle Bell Project','Kai liked helping at the bike path, especially when there was a small job that nobody had planned. One Tuesday, Kai noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('50d7ad30-9a18-53cc-a66c-9ec8331e2976','TEXT','The Orange Tree Calendar — A Different Day','Mia liked helping at the school orchard, especially when there was a small job that nobody had planned. One Tuesday, Mia noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
